<script setup lang="ts">
import { IonButton, IonPage, loadingController } from '@ionic/vue'
import { App } from '@capacitor/app'
import { ref } from 'vue'
import { Uploader, Circle as VanCircle } from 'vant'
import type { AxiosProgressEvent } from 'axios'
import type { UploaderAfterRead } from 'vant/lib/uploader/types'
import ClearIcon from '@/components/svg/ClearIcon.vue'
import AddIconRound from '@/components/svg/AddIconRound.vue'
import { universeService } from '@/services/universe'

interface Props {
  src: string
  closable: boolean
}

interface Emits {
  (e: 'close'): void
  (e: 'play'): void
}
// props with default closable value
const props = defineProps<Props>()
defineEmits<Emits>()

const videoRef = ref<HTMLVideoElement | null>(null)
const uploading = ref(false)
const uploadProgress = ref(0)
const fileName = ref('')
const result = ref('')

App.addListener('appStateChange', (state) => {
  if (state.isActive) {
    videoRef.value?.play()
  }
  else {
    videoRef.value?.pause()
  }
})

function onUploadProgress(e: AxiosProgressEvent) {
  uploadProgress.value = (e?.progress || 0) * 100
}

const afterRead: UploaderAfterRead = async (file: any) => {
  // 此时可以自行将文件上传至服务器
  if (!file?.file.name) {
    return
  }
  const loading = await loadingController.create({
    duration: 5000,
  })
  loading.present()
  const res = await universeService.generateVideoPresignedUrl(file.file.name)
  loading.dismiss()
  if (res.presignedUrl) {
    fileName.value = file.file.name
    uploading.value = true
    try {
      const upload = await universeService.uploadBGM(res.presignedUrl, file.file, onUploadProgress)
      console.log(upload)
      const videoInfo = {
        url: res.s3Prefix,
        name: file.file.name,
      }
      const vid = await universeService.createVideo(videoInfo)
      result.value = `上传 ${vid.name} 成功`
      uploading.value = false
    }
    catch (error) {
      console.error(error)
      uploading.value = false
      result.value = '上传失败'
    }
  }
}
</script>

<template>
  <ion-page class="flex justify-center items-center text-white">
    <uploader class="w-full" accept="*" :after-read="afterRead">
      <div class="upload-card flex flex-1 items-center justify-between p-2 mx-4 my-2">
        <div class="flex items-center gap-2">
          <div class="upload-cover" :style="uploading ? 'unset' : 'background-color: rgba(255, 255, 255, 0.16);'">
            <add-icon-round v-if="uploading === false" />
            <van-circle v-else size="32" :current-rate="uploadProgress" color="#05F0FF" />
          </div>
          <div v-if="uploading === false" class="desc">
            {{ 'Upload your video file' }}
          </div>
          <div v-else>
            Uploading <span class="font-bold">{{ fileName }}</span>
          </div>
        </div>
        <clear-icon v-if="uploading" @click="uploading = false" />
      </div>
    </uploader>
    <div class="mt-4">
      上传结果：{{ result || '无' }}
    </div>
    <ion-button v-if="props.closable" class="absolute top-2 left-2" fill="clear" @click="() => $emit('close')">
      <clear-icon />
    </ion-button>
  </ion-page>
</template>

